export function App() {
  const [route, setRoute] = useState(() => location.hash.replace(/^#/, "") || "/room/main");
  const [variant, setVariant] = useState(() => ["A", "B", "C"].includes(new URLSearchParams(location.search).get("variant") ?? "") ? new URLSearchParams(location.search).get("variant")! : "A");
  const [dark, setDark] = useState(() => matchMedia("(prefers-color-scheme: dark)").matches);
  const [approvals, setApprovals] = useState(initialApprovals); const [messages, setMessages] = useState<LocalMessage[]>([]); const [ledger, setLedger] = useState(initialLedger); const [automations, setAutomations] = useState(initialAutomations); const [control, setControl] = useState<DemoState["control"]>("agent"); const [notice, announce] = useState(""); const [search, setSearch] = useState(false);
  const workflow = useWorkState(announce);
  const library = useAppLibrary(announce);
  const attentionCount = approvals.filter(a => a.status === "pending").length + workflow.work.filter(w => w.status === "input").length + recoverableWork(workflow.work, workflow.receipts).length;
  const go = (path: string) => { location.hash = path; };
  function cycle(direction: number) { const next = ["A", "B", "C"][( ["A", "B", "C"].indexOf(variant) + direction + 3 ) % 3]; setVariant(next); const url = new URL(location.href); url.searchParams.set("variant", next); history.replaceState(null, "", url); announce(`Layout ${next}: ${next === "A" ? "Desk — conversation first" : next === "B" ? "Briefing — decisions first" : "Workbench — work first"}. `); }
  useEffect(() => { document.documentElement.dataset.theme = dark ? "dark" : "light"; }, [dark]);
  useEffect(() => { const onHash = () => { setRoute(location.hash.replace(/^#/, "") || "/room/main"); announce(""); }; addEventListener("hashchange", onHash); return () => removeEventListener("hashchange", onHash); }, []);
  useEffect(() => { const key = (e: KeyboardEvent) => { if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") { e.preventDefault(); setSearch(s => !s); } if (route.startsWith("/room/") && !route.includes("/direct-") && !e.metaKey && !e.ctrlKey && !e.altKey && ["ArrowLeft", "ArrowRight"].includes(e.key) && !(e.target as HTMLElement).closest("input,textarea,[contenteditable=true],[role=dialog],[role=tablist],[role=combobox]")) { e.preventDefault(); cycle(e.key === "ArrowLeft" ? -1 : 1); } }; addEventListener("keydown", key); return () => removeEventListener("keydown", key); }, [route, variant]);
  function record(bot: string, type: string, summary: string, detail: Record<string, unknown>) { setLedger(rows => [{ id: Math.max(0, ...rows.map(r => r.id)) + 1, time: "Now", room: "main", bot, type, summary, detail }, ...rows]); }
  function decide(id: string, status: Approval["status"], body?: string) {
    const a = approvals.find(a => a.id === id); if (!a || a.status !== "pending") return;
    setApprovals(rows => rows.map(row => row.id === id ? { ...row, status, body: status === "edited" ? body ?? row.body : row.body } : row));
    workflow.settleApproval(a, status, body);
    record(a.bot, "approval", `${a.title} · ${status}`, { tool: a.tool, decision: status, execution: ["accepted", "edited"].includes(status) ? "not started" : "not run", previewOnly: true });
    announce(`Decision recorded: “${a.title}” ${status}. No action was executed.`);
  }
  function send(text: string, room: string) { const bot = room.startsWith("direct-") ? room.replace("direct-", "") as BotId : "boss"; setMessages(rows => [...rows, { id: String(Date.now()), bot: "owner", text, room }, { id: String(Date.now() + 1), bot, room, text: "Noted. I’ll keep the work in this conversation and ask before taking a consequential action." }]); record("owner", "message", text.slice(0, 70), { source: "prototype", room, text }); announce("Message added locally."); }
  const ctx: DemoState = { ...workflow, ...library, attentionCount, route, go, approvals, decide, messages, send, ledger, automations, setAutomations, control, setControl, notice, announce };
  const isSettings = settingPages.some(p => route.startsWith(p.path));
  return <AvatarProvider><TooltipProvider><DemoContext.Provider value={ctx}><SidebarProvider style={{ "--sidebar-width": "232px" } as CSSProperties}><AppSidebar /><SidebarInset className="app-main"><Header openSearch={() => setSearch(true)} dark={dark} toggleTheme={() => setDark(!dark)} /><main className="app-content">{route.startsWith("/room/") ? <RoomPage variant={variant} /> : route === "/inbox" ? <NeedsYouPage /> : route === "/work" ? <WorkPage /> : route === "/app-library" ? <AppLibraryPage /> : route === "/computer" ? <ComputerPage /> : route === "/ledger" ? <LedgerPage /> : isSettings ? <div className="settings-layout"><SettingsNav /><div className="settings-content">{route.startsWith("/bots") ? <BotsPage /> : route === "/connectors" ? <InstalledConnectionsPage /> : route === "/automations" ? <AutomationsPage /> : route === "/settings/models" ? <ModelsPage /> : route === "/settings/proactive" ? <ProactivePage /> : route === "/settings/memory" ? <MemoryPage /> : <ServerPage />}</div></div> : <RoomPage variant={variant} />}</main>{((route.startsWith("/room/") && !route.includes("/direct-")) || notice) && <footer className="layout-footer">{notice && <span role="status">{notice}</span>}{route.startsWith("/room/") && !route.includes("/direct-") && <div className="variant-switcher" aria-label="Room layout"><Button variant="ghost" size="icon-xs" aria-label="Previous layout" onClick={() => cycle(-1)}><ArrowLeft /></Button><span><span>{variant} /</span> {variant === "A" ? "Desk" : variant === "B" ? "Briefing" : "Workbench"}</span><Button variant="ghost" size="icon-xs" aria-label="Next layout" onClick={() => cycle(1)}><ArrowRight /></Button></div>}</footer>}</SidebarInset></SidebarProvider>
  <WorkDetailsSheet /><ResultDialog /><AppLibraryDialog /><CommandDialog open={search} onOpenChange={setSearch} title="Search your desk" description="Jump to a room, an agent, or a page."><Command><CommandInput placeholder="Search rooms, agents and settings…" /><CommandList><CommandEmpty>No matching page.</CommandEmpty><CommandGroup heading="Rooms">{["main", "openag", "background"].map(id => <CommandItem key={id} onSelect={() => { go(`/room/${id}`); setSearch(false); }}><Hash />{id}</CommandItem>)}</CommandGroup><CommandGroup heading="Workspace">{[...appPages, ...settingPages].map(p => <CommandItem key={p.path} onSelect={() => { go(p.path); setSearch(false); }}><p.icon />{p.title}</CommandItem>)}</CommandGroup></CommandList></Command></CommandDialog></DemoContext.Provider></TooltipProvider></AvatarProvider>;
}
